'use strict';

// The pure-JS fallback, written as a FUNCTION DECLARATION. Unlike
// ADV2-069's anonymous `let` initializer, this needs no name inference at
// all -- the declaration is literally named `dangerousOp`, which is
// exactly the export name the advisory asks for. It is the easiest
// possible target for a name-based export search.
function dangerousOp(input) {
  return 'safe:' + String(input);
}

// The native addon takes over when it loaded. Whether it did is a
// property of the INSTALL and the ENVIRONMENT; no reader of this file can
// decide it. JavaScript rebinds a function declaration here just as
// freely as it would a `var` -- the declaration form is no protection.
if (process.env.VT2_NATIVE === '1') {
  dangerousOp = require('./native');
}

// GHSA-vt2v2-0001 names THIS export, and by this line the declaration
// above may well have been replaced.
exports.dangerousOp = dangerousOp;

// The explicit escape hatch, for callers that already know the addon is
// present. Whenever the branch above ran this is the SAME function object
// as `dangerousOp` -- and unlike it, this one is statically resolvable
// (RWF-004a), so the call graph reaches native.js's real function through
// this name and never through the reassigned declaration.
exports.dangerousOpNative = require('./native');
